window.SHB_DATA = [{"id":"s1t1","title":"Übung 1 · Teil 1","thema":"Bewerbung","type":"bank","head":"Betreff: Meine Bewerbung vom 3. März","paras":["Sehr geehrte Frau Hoffmann,","herzlichen Dank für Ihre Eingangsbestätigung vom 6. März.","Mir ist natürlich klar, dass die Auswahl der passenden Kandidaten Zeit braucht. {46} würde ich gerne erfahren, wie der aktuelle Stand meiner Bewerbung ist.","Könnten Sie mir bitte kurz mitteilen, {47} Sie meine Unterlagen {48} prüfen konnten?","An der Stelle als Sachbearbeiter im Einkauf bin ich nach wie vor sehr interessiert.","Da ich {49} drei Wochen einen Kurs zum Thema SAP abgeschlossen habe, sende ich Ihnen anbei das Zertifikat.","Falls Ihnen noch Unterlagen fehlen, reiche ich diese gerne {50} nach. {51} meiner Erfahrung im Einkauf bin ich überzeugt, dass ich gut in Ihr Team passe.","Ich freue mich auf ein persönliches Gespräch.","Mit freundlichen Grüßen<br>Mykola Bondar"],"bank":[["a","wann"],["b","deswegen"],["c","aufgrund"],["d","außerdem"],["e","inzwischen"],["f","dennoch"],["g","daher"],["h","vor"],["i","sofort"],["j","ob"]],"key":{"46":"f","47":"j","48":"e","49":"h","50":"i","51":"c"},"cap":[46,51],"topic":{"46":"Konnektor","47":"Konnektor","48":"Adverb","49":"Präposition","50":"Adverb","51":"Präposition"},"why":{"46":"dennoch — «тем не менее»: понимаю, что нужно время, и всё же спрашиваю. Это уступка. daher и deswegen («поэтому») дали бы причину — по смыслу не подходит.","47":"ob — косвенный вопрос «ли»: проверили ли уже документы. wann спрашивает «когда».","48":"inzwischen — «уже, к этому моменту».","49":"vor + Dat. — «назад»: vor drei Wochen — три недели назад.","50":"sofort nachreichen — сразу дослать документы.","51":"aufgrund + Gen. — «на основании, благодаря»: aufgrund meiner Erfahrung."},"extra":"Лишние: wann, deswegen, daher, außerdem."},{"id":"s1t2","title":"Übung 1 · Teil 2","thema":"Auftragsbestätigung","type":"abc","head":"Auftragsbestätigung","paras":["Sehr geehrte Frau Krüger,","vielen Dank für Ihre Bestellung vom 14.05.20xx, die Sie uns über unser Online-Portal geschickt haben. Nachfolgend bestätigen wir die bestellten Artikel auf Grundlage {52}.","<div class=\"shb-tw\"><table class=\"shb-t\"><tr><th>Pos.</th><th>Menge</th><th>Artikel</th><th>Einzelpreis</th><th>Gesamtpreis</th></tr><tr><td>1</td><td>40</td><td>Bürostuhl „Ergo Plus“</td><td>249,00</td><td>9.960,00 Euro</td></tr><tr><td>2</td><td>40</td><td>Schreibtischlampe LED</td><td>39,00</td><td>1.560,00 Euro</td></tr><tr><td></td><td></td><td></td><td>Summe netto</td><td>11.520,00 Euro</td></tr><tr><td></td><td></td><td></td><td>19 % MwSt.</td><td>2.188,80 Euro</td></tr><tr><td></td><td></td><td></td><td>Gesamtbetrag</td><td>13.708,80 Euro</td></tr></table></div>","Wir garantieren Ihnen eine {53} und freuen uns auf {54}! Die Lieferung erfolgt in der KW 22.","Bei {55} der Lieferung wenden Sie sich bitte an Herrn Petersen, der Ihnen unter der Nummer 0711 4567-23 {56} steht. Wir bitten Sie {57} und Rücksendung dieser Auftragsbestätigung bis zum 20.05.20xx.","Mit freundlichen Grüßen<br>Lena Brandt"],"items":[{"n":52,"o":["unserem Angebot","unserer Bestellung","unseres Angebots"],"a":2,"t":"Präposition","w":"auf Grundlage + Gen. — «на основании»: auf Grundlage unseres Angebots. Нужен Genitiv, поэтому не unserem; заказ (Bestellung) делает клиент, а не продавец."},{"n":53,"o":["sorgfältige Abwicklung","vielfältige Aufgabe","günstige Kündigung"],"a":0,"t":"Wortschatz","w":"eine sorgfältige Abwicklung garantieren — гарантировать тщательное выполнение заказа."},{"n":54,"o":["einen langen Urlaub","eine gute Zusammenarbeit","eine schwierige Aufgabe"],"a":1,"t":"Wortschatz","w":"sich freuen auf eine gute Zusammenarbeit — стандартная концовка делового письма."},{"n":55,"o":["Antworten im Laufe","Fragen im Zuge","Wünschen trotz"],"a":1,"t":"Präposition","w":"im Zuge + Gen. — «в ходе»: Fragen im Zuge der Lieferung — вопросы в ходе поставки."},{"n":56,"o":["gerne zur Beratung","gerne zur Diskussion","gerne zur Verfügung"],"a":2,"t":"Nomen-Verb-Verbindung","w":"jdm. gerne zur Verfügung stehen — охотно быть в распоряжении."},{"n":57,"o":["um Unterzeichnung","um Unterstützung","um Untersuchung"],"a":0,"t":"Rektion","w":"jdn. um etw. bitten — просить о чём-то: um Unterzeichnung und Rücksendung — подписать и вернуть."}]},{"id":"s2t1","title":"Übung 2 · Teil 1","thema":"Kündigung (Ausbildung)","type":"bank","head":"Kündigung Ihres Ausbildungsvertrages","paras":["Sehr geehrter Herr Yilmaz,","hiermit kündigen wir den am 01.09.20xx mit Ihnen geschlossenen Ausbildungsvertrag zum Fachlageristen.","Zur Begründung:","{46} von Ihnen unterschriebene Ausbildungsvertrag {47} in § 6 die Vereinbarung, dass Sie Ihre Arbeit um 7:00 Uhr beginnen. {48} sind Sie am 12.10. erst um 7:25 Uhr im Lager erschienen. Am 19.10. kamen Sie {49} um 7:40 Uhr. Auch am 02.11. haben Sie Ihre Schicht verspätet angetreten.","In unserem Gespräch am 05.11., an dem auch die Ausbildungsleiterin Frau Kraus teilgenommen hat, konnten Sie für Ihre Verspätungen keine Erklärung geben. Am 09.11. sind Sie erneut zu spät gekommen.","Da wir {50} unserer Lieferzeiten auf ein pünktliches Erscheinen aller Mitarbeiter angewiesen sind, beanstanden wir Ihr Verhalten {51} ausdrücklich.","Aus den genannten Gründen endet das Ausbildungsverhältnis zum 31.12.20xx.","Mit freundlichen Grüßen<br>Sabine Lorenz<br>Personalabteilung"],"bank":[["a","trotz"],["b","dem"],["c","der"],["d","erst"],["e","gleichwohl"],["f","enthält"],["g","obwohl"],["h","aufgrund"],["i","bekommt"],["j","hiermit"]],"key":{"46":"c","47":"f","48":"e","49":"d","50":"h","51":"j"},"cap":[46,48],"topic":{"46":"Deklination","47":"Wortschatz","48":"Konnektor","49":"Adverb","50":"Präposition","51":"Adverb"},"why":{"46":"der — Nominativ: договор здесь подлежащее. Подсказка — окончание unterschriebene: после dem было бы unterschriebenen.","47":"enthält — «содержит»: der Vertrag enthält eine Vereinbarung. bekommt по смыслу не подходит.","48":"gleichwohl — «тем не менее» (= trotzdem): договорённость есть, а вы всё равно опоздали. trotz — предлог, ему нужно существительное; obwohl — союз, глагол ушёл бы в конец.","49":"erst — «только, не раньше»: erst um 7:40 Uhr — то есть с опозданием.","50":"aufgrund + Gen. — «из-за, в силу»: aufgrund unserer Lieferzeiten.","51":"hiermit — «настоящим»: официальная формула beanstanden wir hiermit ausdrücklich."},"extra":"Лишние: trotz, dem, obwohl, bekommt."},{"id":"s2t2","title":"Übung 2 · Teil 2","thema":"Auftragsbestätigung","type":"abc","head":"Auftragsbestätigung","paras":["Sehr geehrter Herr Wagner,","herzlichen Dank für {52} vom 03.03.20xx, den wir Ihnen hiermit gerne bestätigen.","Die technischen Details der Drucker entnehmen Sie bitte Seite 4 {53} vom 20.02.20xx.","{54} eines Liefertermins wird sich unser Kundenservice in der KW 12 telefonisch bei Ihnen melden.","Die Geräte werden spätestens am 31.03.20xx an Ihre Filiale in Stuttgart, Königstraße 15, geliefert.","Wir bedanken uns herzlich für {55} und Ihren Auftrag und freuen uns auf eine {56} mit Ihrem Unternehmen.","Bei Rückfragen steht Ihnen Frau Melanie Schulz montags bis freitags von 8:00 bis 16:00 Uhr gerne {57}.","Mit freundlichen Grüßen<br>Tobias Keller"],"items":[{"n":52,"o":["unseren Auftrag","Ihren Auftrag","Ihre Anfrage"],"a":1,"t":"Wortschatz","w":"Ihren Auftrag — заказ сделал клиент, мы его подтверждаем. «den» указывает на мужской род (der Auftrag); у Anfrage было бы «die»."},{"n":53,"o":["unserer Bestellung","unserer Abwicklung","unseres Angebots"],"a":2,"t":"Wortschatz","w":"unseres Angebots — Genitiv: страница 4 нашего предложения. Заказывал клиент, поэтому не «unserer Bestellung»."},{"n":54,"o":["Zwecks Vereinbarung","Mangels Interesse","Aufgrund von"],"a":0,"t":"Präposition","w":"zwecks + Gen. — «с целью»: zwecks Vereinbarung eines Liefertermins — чтобы согласовать дату поставки. mangels — «из-за отсутствия»."},{"n":55,"o":["Ihre Lieferung","Ihre Beschwerde","Ihr Vertrauen"],"a":2,"t":"Wortschatz","w":"für Ihr Vertrauen — стандартная благодарность клиенту."},{"n":56,"o":["gute Zusammenarbeit","lange Pause","fröhliche Feier"],"a":0,"t":"Wortschatz","w":"auf eine gute Zusammenarbeit — стандартная концовка делового письма."},{"n":57,"o":["zur Bearbeitung","zur Verfügung","zur Aufnahme"],"a":1,"t":"Nomen-Verb-Verbindung","w":"jdm. zur Verfügung stehen — быть в распоряжении."}]},{"id":"s3t1","title":"Übung 3 · Teil 1","thema":"Kündigung","type":"bank","head":"Meine Kündigung zum 30.06.20xx","paras":["Sehr geehrter Herr Neumann,","wie Ihnen bekannt ist, habe ich mein Arbeitsverhältnis fristgerecht zum 30.06.20xx gekündigt, da ich mit meiner Familie nach Hamburg umziehe. {46} heute habe ich mein Arbeitszeugnis leider nicht erhalten.","Ich möchte betonen, {47} ein qualifiziertes Zeugnis für meine Bewerbungen sehr wichtig ist. Ich habe nicht nur sieben Jahre als Buchhalterin in Ihrem Unternehmen gearbeitet, {48} auch mehrere Schulungen zum Thema DATEV besucht. Bitte bestätigen Sie im Zeugnis auch meine Teilnahme {49} diesen Schulungen.","Außerdem möchte ich mich {50} bedanken, dass ich in Ihrem Team so viel lernen durfte. Ich blicke gerne {51} zurück.","Ich danke Ihnen im Voraus für Ihre Mühe.","Mit freundlichen Grüßen<br>Anna Petrenko"],"bank":[["a","darauf"],["b","dafür"],["c","bis"],["d","seit"],["e","dass"],["f","vor"],["g","sondern"],["h","obwohl"],["i","auf"],["j","an"]],"key":{"46":"c","47":"e","48":"g","49":"j","50":"b","51":"a"},"cap":[46],"topic":{"46":"Präposition","47":"Konnektor","48":"Konnektor","49":"Rektion","50":"da-Wort","51":"da-Wort"},"why":{"46":"bis heute — «до сих пор». seit heute — «с сегодняшнего дня», по смыслу не подходит.","47":"dass — придаточное после betonen: «подчеркнуть, что…».","48":"nicht nur …, sondern auch — «не только…, но и».","49":"die Teilnahme an + Dat. — участие в чём-то: Teilnahme an diesen Schulungen.","50":"sich dafür bedanken, dass … — da-Wort заранее указывает на придаточное с dass: sich bedanken für → dafür.","51":"zurückblicken auf + Akk. → darauf: «с удовольствием вспоминаю об этом». Просто auf без объекта нельзя."},"extra":"Лишние: seit, vor, obwohl, auf."},{"id":"s3t2","title":"Übung 3 · Teil 2","thema":"Anfrage","type":"abc","head":"Anfrage Online-Sprachkurse","paras":["Sehr geehrte Frau Dr. Weber,","wir sind ein {52} für Logistikdienstleistungen in Süddeutschland. Auf der Messe „Personal Süd“ in Stuttgart sind wir auf Ihr {53} im Bereich der Online-Sprachkurse aufmerksam geworden.","Besonders interessiert uns Ihr Kurs „Deutsch im Beruf B2“. Wir möchten Sie daher um ein Beratungsgespräch bitten, in dem unsere Personalabteilung über den Kurs ausführlich informiert wird. Außerdem benötigen wir eine {54} aller Kosten, falls wir den Kurs für unsere Mitarbeiter buchen.","Eine Übersicht, aus der hervorgeht, {55} Sie Gruppenrabatte gewähren, wäre für uns ebenfalls interessant.","Wir haben insgesamt 85 Mitarbeiter an drei Standorten. Falls Sie noch Fragen {56} haben, bitten wir Sie, mit unserem Personalleiter, Herrn Jan Koch, {57}. Er beantwortet Ihre Fragen gerne.","Wir freuen uns auf Ihre Antwort.","Mit freundlichen Grüßen<br>Petra Schmid"],"items":[{"n":52,"o":["führender Anbieter","bekannte Unternehmen","große Firma"],"a":0,"t":"Deklination","w":"ein führender Anbieter — «ведущий поставщик». ein + мужской род → окончание -er. Unternehmen — средний род (ein bekanntes), Firma — женский (eine)."},{"n":53,"o":["vielfältige Kurse","breites Angebot","großes Interesse"],"a":1,"t":"Wortschatz","w":"auf Ihr breites Angebot aufmerksam werden — обратить внимание на ваш широкий выбор. Kurse — мн. ч., было бы Ihre; Interesse по смыслу не подходит."},{"n":54,"o":["kurze Mitteilung","bezahlte Rechnung","detaillierte Aufstellung"],"a":2,"t":"Wortschatz","w":"eine detaillierte Aufstellung aller Kosten — подробный перечень всех расходов."},{"n":55,"o":["mit welchen Mitteln","unter welchen Bedingungen","laut welchem Gesetz"],"a":1,"t":"Wortschatz","w":"unter welchen Bedingungen — «на каких условиях» вы даёте скидки группам."},{"n":56,"o":["bezüglich unserer Anfrage","infolge unserer Bestellung","trotz unserer Anfrage"],"a":0,"t":"Präposition","w":"bezüglich + Gen. — «касательно»: Fragen bezüglich unserer Anfrage. infolge — «вследствие», а заказа ещё нет."},{"n":57,"o":["telefonisch zu verhandeln","mitzuteilen","Kontakt aufzunehmen"],"a":2,"t":"Nomen-Verb-Verbindung","w":"mit jdm. Kontakt aufnehmen — связаться с кем-то."}]},{"id":"s4t1","title":"Übung 4 · Teil 1","thema":"Bewerbung / Nachfrage","type":"bank","head":"Betreff: Meine Bewerbung vom 10.09.20xx","paras":["Sehr geehrte Damen und Herren,","vielen Dank für Ihre freundliche E-Mail vom 12.09.20xx. {46} sind seit dem Ende der Bewerbungsfrist drei Wochen vergangen. {47} möchte ich mich erkundigen, wie das Auswahlverfahren weitergeht.","Ich interessiere mich nach wie vor sehr für die Stelle als Berufskraftfahrer in Ihrer Spedition und würde mich über eine positive Antwort freuen.","Da ich {48} noch ein Angebot von einer anderen Firma bekommen habe, wäre es hilfreich, wenn Sie mir mitteilen könnten, {49} ich spätestens mit einer Entscheidung rechnen kann. {50} des kurzen Arbeitswegs würde ich aber lieber bei Ihnen arbeiten.","Für Fragen {51} meinem Lebenslauf erreichen Sie mich jederzeit per E-Mail oder unter 0176 1234567.","Vielen Dank für Ihre Mühe.","Mit freundlichen Grüßen<br>Oleksandr Melnyk"],"bank":[["a","inzwischen"],["b","daher"],["c","ob"],["d","wann"],["e","auch"],["f","über"],["g","trotz"],["h","aufgrund"],["i","da"],["j","zu"]],"key":{"46":"a","47":"b","48":"e","49":"d","50":"h","51":"j"},"cap":[46,47,50],"topic":{"46":"Adverb","47":"Konnektor","48":"Adverb","49":"Konnektor","50":"Präposition","51":"Rektion"},"why":{"46":"inzwischen — «тем временем, уже»: прошло уже три недели.","47":"daher — «поэтому»: прошло три недели → поэтому спрашиваю. Сравни с Übung 1: там «понимаю, что нужно время» → dennoch (уступка).","48":"auch noch — «ещё и, вдобавок»: получил предложение ещё и от другой фирмы.","49":"wann — косвенный вопрос о времени: wann ich spätestens … rechnen kann. ob не сочетается со spätestens.","50":"aufgrund + Gen. — «из-за, благодаря»: aufgrund des kurzen Arbeitswegs. trotz дал бы противоречие.","51":"Fragen zu + Dat. — вопросы по чему-то: zu meinem Lebenslauf. Подсказка — meinem (Dativ); über требовал бы Akk.: meinen."},"extra":"Лишние: ob, über, trotz, da."},{"id":"s4t2","title":"Übung 4 · Teil 2","thema":"Auftragserteilung","type":"abc","head":"Auftragserteilung","paras":["Sehr geehrter Herr Fischer,","wir danken Ihnen für das informative Gespräch am 05.05.20xx, in dem Sie uns {52} noch einmal ausführlich vorgestellt haben.","Wir sind ein Hotel mit 120 Zimmern in der Innenstadt von Freiburg und möchten unseren Frühstücksraum modernisieren. Deshalb möchten wir unseren {53} erweitern.","Ihre Kaffeemaschinen haben uns nicht nur technisch überzeugt, sondern uns auch dazu veranlasst, die bereits {54} zu erhöhen.","Gemäß Ihrem Angebot vom 20.04. bestellen wir:<br>4 Kaffeevollautomaten „Barista Pro“<br>8 Milchkühler „Fresh“<br>2 Wartungspakete für 24 Monate","Wir erwarten die Lieferung bis zum 15.06. Wie vereinbart, sind alle {55} Nettopreise. Bitte schicken Sie uns eine {56}.","Wenn die Lieferung zu unserer Zufriedenheit erfolgt, können Sie {57}.","Mit freundlichen Grüßen<br>Markus Engel"],"items":[{"n":52,"o":["Ihre Anfrage","Ihre Angaben","Ihr Angebot"],"a":2,"t":"Wortschatz","w":"Ihr Angebot — на встрече поставщик представил своё предложение; ниже: Gemäß Ihrem Angebot. Запрос (Anfrage) делает покупатель."},{"n":53,"o":["neue Bestellung","letzten Auftrag","vorherige Lieferung"],"a":1,"t":"Deklination","w":"unseren letzten Auftrag — unseren = Akk. мужского рода → der Auftrag. Bestellung и Lieferung — женского рода, было бы unsere."},{"n":54,"o":["bestellte Menge","geplante Auslieferung","besprochene Einlieferung"],"a":0,"t":"Wortschatz","w":"die bereits bestellte Menge erhöhen — увеличить уже заказанное количество."},{"n":55,"o":["genannten Preise","bezahlten Rechnungen","gesendeten Kalkulationen"],"a":0,"t":"Wortschatz","w":"alle genannten Preise sind Nettopreise — все названные цены указаны без НДС."},{"n":56,"o":["prompte Bearbeitung","zuverlässige Ausführung","kurze Auftragsbestätigung"],"a":2,"t":"Wortschatz","w":"eine kurze Auftragsbestätigung schicken — прислать подтверждение заказа. «Обработку» (Bearbeitung) прислать нельзя."},{"n":57,"o":["auf weitere Rabatte verzichten","mit weiteren Aufträgen rechnen","die Bestellung stornieren"],"a":1,"t":"Rektion","w":"mit weiteren Aufträgen rechnen — «можете рассчитывать на новые заказы»; rechnen mit + Dat."}]},{"id":"s5t1","title":"Übung 5 · Teil 1","thema":"Bewerbung","type":"bank","head":"Meine Bewerbung als Verkäufer im Elektronikmarkt","paras":["Sehr geehrte Frau Albrecht,","{46} drei Jahren im Kundenservice möchte ich mich beruflich weiterentwickeln. Ihre Stellenanzeige hat mich sofort angesprochen, denn ich erfülle alle Voraussetzungen {47}. Ich bin sicher, dass ich Ihr Team gut verstärken kann.","Für mich steht der Kunde im Mittelpunkt. Ich möchte, dass jeder Kunde {48} das Richtige für sich findet. Deshalb empfehle ich {49} Produkte, die ich selbst getestet habe. Und was gibt es Schöneres {50} einen zufriedenen Kunden, der gerne wiederkommt?","Ich suche eine langfristige Stelle. Arbeit am Wochenende ist für mich kein Problem. Ich könnte ab dem 01.03.20xx bei Ihnen anfangen.","{51} beantworte ich Ihre Fragen in einem persönlichen Gespräch.","Mit freundlichen Grüßen<br>Dmytro Koval"],"bank":[["a","nur"],["b","gern"],["c","sowie"],["d","für"],["e","nach"],["f","ob"],["g","als"],["h","dafür"],["i","in"],["j","genau"]],"key":{"46":"e","47":"h","48":"j","49":"a","50":"g","51":"b"},"cap":[51],"topic":{"46":"Präposition","47":"da-Wort","48":"Adverb","49":"Adverb","50":"Konnektor","51":"Adverb"},"why":{"46":"nach + Dat. — «после»: nach drei Jahren — после трёх лет. in drei Jahren означало бы «через три года».","47":"die Voraussetzungen dafür erfüllen — соответствовать требованиям (для этой работы): dafür = «для этого».","48":"genau das Richtige — «именно то, что нужно». Устойчивое выражение.","49":"nur — «только»: рекомендую только то, что проверил сам.","50":"Schöneres … als — сравнение: «что может быть лучше, чем…». После сравнительной степени — als.","51":"Gern beantworte ich Ihre Fragen — «охотно отвечу», вежливая концовка письма."},"extra":"Лишние: sowie, für, ob, in."},{"id":"s5t2","title":"Übung 5 · Teil 2","thema":"Angebot","type":"abc","head":"Ihre Anfrage","paras":["Sehr geehrter Herr Lehmann,","vielen Dank für das angenehme Telefongespräch und Ihre Anfrage. Wie besprochen, finden Sie im Anhang {52} zu unserer Buchhaltungssoftware „KontoKlar“ für kleine und mittlere Unternehmen.","Als erfahrener Anbieter für den {53} in der Buchhaltung bieten wir Ihnen eine einfache Lösung für Rechnungen, Belege und die Steuererklärung.","Gerne können wir Ihnen die Software 30 Tage lang kostenlos {54}. Danach gilt eine {55}.","Wenn Sie einen {56} möchten, wenden Sie sich bitte an Frau Yildiz, denn sie ist für Verträge zuständig.","Wir freuen uns auf {57} und hoffen, Sie bald zu unseren zufriedenen Kunden zählen zu dürfen.","Mit freundlichen Grüßen<br>Jonas Roth"],"items":[{"n":52,"o":["unsere aktuelle Rechnung","unser aktuelles Angebot","Ihre aktuelle Bestellung"],"a":1,"t":"Wortschatz","w":"unser aktuelles Angebot — в приложении наше предложение. Счёта (Rechnung) ещё нет, а заказ (Bestellung) делает клиент."},{"n":53,"o":["professionellen Einsatz","internationalen Handel","privaten Urlaub"],"a":0,"t":"Wortschatz","w":"für den professionellen Einsatz — «для профессионального использования»."},{"n":54,"o":["in Rechnung stellen","in Auftrag geben","zur Verfügung stellen"],"a":2,"t":"Nomen-Verb-Verbindung","w":"kostenlos zur Verfügung stellen — предоставить бесплатно. in Rechnung stellen — выставить счёт, это противоречит kostenlos."},{"n":55,"o":["interne Absprache","freundliche Beratung","monatliche Kündigungsfrist"],"a":2,"t":"Wortschatz","w":"eine monatliche Kündigungsfrist — срок расторжения — один месяц."},{"n":56,"o":["Telefongespräch führen","Jahresvertrag abschließen","wichtiges Angebot machen"],"a":1,"t":"Deklination","w":"einen Jahresvertrag abschließen — заключить годовой договор; за договоры отвечает Frau Yildiz. Telefongespräch и Angebot — среднего рода: было бы ein, а не einen."},{"n":57,"o":["Ihre Bestellung","Ihre Anfrage","unser Angebot"],"a":0,"t":"Wortschatz","w":"sich freuen auf Ihre Bestellung — «будем рады вашему заказу». Запрос уже был, а предложение делает сама фирма."}]},{"id":"s6t1","title":"Übung 6 · Teil 1","thema":"Ausbildung","type":"bank","head":"","paras":["Sehr geehrter Herr Brenner,","nach unserem netten Telefonat bin ich noch motivierter als {46}, bei Ihnen die Ausbildung zur Kauffrau für Spedition und Logistikdienstleistung zu beginnen.","Eine lange Einarbeitung ist bei mir nicht nötig, weil ich Ihre Firma {47} kenne. {48} meines Praktikums in Ihrer Disposition (vom 01.04. bis 31.05.20xx) habe ich Transporte geplant und Frachtpapiere vorbereitet. Mein damaliger Betreuer, Herr Vogel, wird Ihnen {49} bestätigen, dass ich zuverlässig gearbeitet habe. Meine Erfahrungen aus dem Praktikum {50} meine guten Englischkenntnisse möchte ich in Ihrem Team einsetzen.","In einem persönlichen Gespräch würde ich Sie gerne {51} überzeugen, dass ich die richtige Auszubildende für Ihr Unternehmen bin.","Mit freundlichen Grüßen<br>Iryna Shevchenko"],"bank":[["a","während"],["b","davon"],["c","weshalb"],["d","würden"],["e","gern"],["f","bereits"],["g","sowie"],["h","seit"],["i","zuvor"],["j","das"]],"key":{"46":"i","47":"f","48":"a","49":"e","50":"g","51":"b"},"cap":[48],"topic":{"46":"Adverb","47":"Adverb","48":"Präposition","49":"Adverb","50":"Konnektor","51":"da-Wort"},"why":{"46":"als zuvor — «чем раньше»: noch motivierter als zuvor — мотивирована ещё больше, чем до разговора.","47":"bereits — «уже»: я уже знаю вашу фирму (по практике).","48":"während + Gen. — «во время»: während meines Praktikums.","49":"gern bestätigen — «охотно подтвердит».","50":"sowie — «а также»: соединяет два подлежащих — Erfahrungen sowie Englischkenntnisse.","51":"jdn. davon überzeugen, dass … — da-Wort указывает на придаточное с dass: überzeugen von → davon."},"extra":"Лишние: weshalb, würden, seit, das."},{"id":"s6t2","title":"Übung 6 · Teil 2","thema":"Auftragserteilung","type":"abc","head":"Auftragserteilung: Dachsanierung Lindenweg 8, Calw","paras":["Sehr geehrte Damen und Herren,","hiermit bestätigen wir den bereits am 12.03.20xx telefonisch {52} gemäß {53} vom 28.02.20xx für die Sanierung des Daches, wie dort beschrieben.","Die Auftragssumme beträgt nach Prüfung 86.400 Euro zuzüglich der {54} in Höhe von 19 %. Das vereinbarte Skonto von 2 % gilt bei Zahlung innerhalb von 10 Tagen.","Die Preise des Angebots sind Festpreise. In unseren Gesprächen haben wir {55} Folgendes vereinbart:","1. Die Arbeiten beginnen am 02.05.20xx.<br>2. Die Arbeiten sind bis zum 30.06.20xx abzuschließen.<br>3. Sie stellen uns eine Gewährleistungsbürgschaft in Höhe von 5 % der Auftragssumme.","Wenn Sie noch Fragen {56} haben, rufen Sie mich gerne an. Wir freuen uns auf eine {57}.","Mit freundlichen Grüßen<br>Klaus Bauer"],"items":[{"n":52,"o":["neues Angebot","ausführliche Beratung","erteilten Auftrag"],"a":2,"t":"Deklination","w":"den … erteilten Auftrag — подтверждаем заказ, уже выданный по телефону. den требует мужского рода (der Auftrag)."},{"n":53,"o":["Ihrem Angebot","Ihrer Bestellung","Ihres Interesses"],"a":0,"t":"Präposition","w":"gemäß + Dat. — «согласно»: gemäß Ihrem Angebot. Предложение делал подрядчик, заказ выдаёт заказчик — автор письма."},{"n":54,"o":["möglichen Versandkosten","gesetzlichen Mehrwertsteuer","geplanten Rabatte"],"a":1,"t":"Wortschatz","w":"zuzüglich der gesetzlichen Mehrwertsteuer — «плюс НДС по закону». 19 % — это ставка НДС."},{"n":55,"o":["laut Anspruch","zusätzlich","nach Bedarf"],"a":1,"t":"Adverb","w":"zusätzlich — «дополнительно»: кроме цен договорились ещё о трёх пунктах."},{"n":56,"o":["statt der Auftragsaufhebung","in Bezug auf den Urlaub","bezüglich der Auftragserteilung"],"a":2,"t":"Präposition","w":"bezüglich + Gen. — «касательно»: Fragen bezüglich der Auftragserteilung."},{"n":57,"o":["gute Zusammenarbeit","schnelle Kündigung","unverbindliches Angebot"],"a":0,"t":"Wortschatz","w":"sich freuen auf eine gute Zusammenarbeit — стандартная концовка письма."}],"extra":"Полезные слова: der/das Skonto — скидка за быструю оплату; die Gewährleistungsbürgschaft — гарантия на устранение дефектов."},{"id":"s7t1","title":"Übung 7 · Teil 1","thema":"Kündigung","type":"bank","head":"Kündigung zum 31.03.20xx","paras":["Sehr geehrte Frau Schäfer,","wie Sie ja {46} wissen, arbeite ich seit 2019 als Sachbearbeiter in Ihrer Versicherungsagentur. {47} meinen Umzug nach Bremen bedingt, muss ich mein Arbeitsverhältnis leider fristgerecht zum 31.03.20xx kündigen.","Da ich den Nachweis für meinen neuen Mietvertrag brauche, bestätigen Sie mir bitte {48} schriftlich den Eingang dieser Kündigung.","Außerdem bitte ich Sie {49} ein qualifiziertes Arbeitszeugnis bis zum 15.03.20xx, da ich es bei meinem neuen Arbeitgeber vorlegen muss.","Ich möchte mich bei Ihnen {50} herzlich bedanken. Ich konnte mich in Ihrem Team nicht nur fachlich weiterentwickeln, {51} habe auch viele nette Kolleginnen und Kollegen kennengelernt.","Bei Rückfragen erreichen Sie mich jederzeit.","Mit freundlichen Grüßen<br>Viktor Hrytsenko"],"bank":[["a","sicherlich"],["b","keineswegs"],["c","pro"],["d","umgehend"],["e","nochmals"],["f","kaum"],["g","das"],["h","sondern"],["i","um"],["j","durch"]],"key":{"46":"a","47":"j","48":"d","49":"i","50":"e","51":"h"},"cap":[47],"topic":{"46":"Adverb","47":"Präposition","48":"Adverb","49":"Rektion","50":"Adverb","51":"Konnektor"},"why":{"46":"wie Sie ja sicherlich wissen — «как вы, наверное, знаете». keineswegs («ни в коем случае») противоречит смыслу.","47":"durch + Akk. … bedingt — «обусловленный чем-то»: durch meinen Umzug bedingt — из-за переезда.","48":"umgehend — «незамедлительно»: подтверждение нужно срочно — для договора аренды.","49":"jdn. um etw. bitten — просить о чём-то: Ich bitte Sie um ein Arbeitszeugnis.","50":"sich nochmals herzlich bedanken — «ещё раз сердечно поблагодарить». kaum («едва») по смыслу не подходит.","51":"nicht nur …, sondern (auch) — «не только…, но и»."},"extra":"Лишние: keineswegs, pro, kaum, das."},{"id":"s7t2","title":"Übung 7 · Teil 2","thema":"Anfrage","type":"abc","head":"Ihre Anfrage","paras":["Sehr geehrter Herr Kowalski,","vielen Dank für Ihr Interesse an {52}. Gerne erstellen wir Ihnen ein Angebot für 150 Paar Sicherheitsschuhe des Modells „Safe Step S3“. {53} brauchen wir noch einige Informationen von Ihnen.","Bitte teilen Sie uns mit, ob die Schuhe an Ihr Lager in Ulm oder an Ihre Zentrale in Augsburg geliefert werden sollen. Außerdem benötigen wir Angaben über den {54}.","Für die Größenauswahl sendet Ihnen unser Kundendienst gerne eine Tabelle zu.","Sollten in der Zwischenzeit {55}, wenden Sie sich bitte an Ihre Ansprechpartnerin, Frau Novak. Frau Novak kümmert sich um {56}, die bei der Bestellung auftreten können, und findet mit Ihnen eine Lösung.","Wir freuen uns auf {57}.","Mit freundlichen Grüßen<br>Sandra Weiß"],"items":[{"n":52,"o":["unserem Angebot","unseren Produkten","Ihren Bestellungen"],"a":1,"t":"Rektion","w":"Interesse an + Dat. — интерес к: an unseren Produkten. Предложения (Angebot) ещё нет — его только составят."},{"n":53,"o":["Trotzdem","Dagegen","Dafür"],"a":2,"t":"da-Wort","w":"dafür — «для этого»: чтобы составить предложение, нужна информация. trotzdem («тем не менее») и dagegen («напротив») — противопоставления здесь нет."},{"n":54,"o":["gewünschten Liefertermin","fröhlichen Feierabend","letzten Urlaub"],"a":0,"t":"Wortschatz","w":"Angaben über den gewünschten Liefertermin — сведения о желаемом сроке поставки."},{"n":55,"o":["alle Probleme gelöst sein","keine Wünsche bestehen","weitere Fragen auftauchen"],"a":2,"t":"Wortschatz","w":"Sollten weitere Fragen auftauchen, … — «если появятся вопросы». Остальные варианты противоречат смыслу."},{"n":56,"o":["alle Probleme","das Problem","jeden Fehler"],"a":0,"t":"Relativpronomen","w":"alle Probleme, die … auftreten können — относительное местоимение die (мн. ч.) подходит только к Probleme. Для das Problem было бы das, для jeden Fehler — den."},{"n":57,"o":["unseren kommenden Termin","Ihre baldige Rückmeldung","Ihre letzte Beschwerde"],"a":1,"t":"Wortschatz","w":"sich freuen auf Ihre baldige Rückmeldung — «будем рады вашему скорому ответу»."}]},{"id":"s8t1","title":"Übung 8 · Teil 1","thema":"Umschulung","type":"bank","head":"Umschulung","paras":["Sehr geehrte Damen und Herren,","da ich meinen Beruf als Elektriker aus gesundheitlichen Gründen nicht mehr ausüben kann, bewerbe ich mich {46} um einen Umschulungsplatz als Fachinformatiker für Systemintegration, den Sie auf Ihrer Website ausgeschrieben haben.","Schon seit Jahren helfe ich nicht nur meiner Familie, {47} auch Freunden und Nachbarn bei Problemen mit Computern und Netzwerken. Deshalb habe ich mich für diese Umschulung entschieden.","{48} meine Arbeit als Elektriker bin ich es gewohnt, sorgfältig und sicher zu arbeiten. Fehler können auf der Baustelle gefährlich sein, {49} ich immer sehr genau arbeite.","In Ihrer Anzeige steht, dass Sie Umschüler aus einem Umkreis von 30 km suchen. {50} ist für mich kein Problem, da ich bereit bin, nach Karlsruhe umzuziehen.","{51} wird meine Umschulung von der Agentur für Arbeit gefördert.","Ich würde mich sehr über eine Einladung zum Vorstellungsgespräch freuen.","Mit freundlichen Grüßen<br>Serhii Bondarenko"],"bank":[["a","dies"],["b","des Weiteren"],["c","obwohl"],["d","trotz"],["e","durch"],["f","sondern"],["g","weshalb"],["h","deren"],["i","hiermit"],["j","darüber"]],"key":{"46":"i","47":"f","48":"e","49":"g","50":"a","51":"b"},"cap":[48,50,51],"topic":{"46":"Adverb","47":"Konnektor","48":"Präposition","49":"Konnektor","50":"Pronomen","51":"Konnektor"},"why":{"46":"sich hiermit bewerben — «настоящим подаю заявку». Стандартная формула.","47":"nicht nur …, sondern auch — «не только…, но и».","48":"durch + Akk. — «благодаря»: durch meine Arbeit als Elektriker. trotz требовал бы Genitiv (meiner) и дал бы противоречие.","49":"weshalb — «поэтому, из-за чего»: союз с глаголом в конце (…, weshalb ich immer sehr genau arbeite). obwohl («хотя») даёт противоречие.","50":"dies — «это» в роли подлежащего: Dies ist für mich kein Problem.","51":"des Weiteren — «кроме того»: ещё один довод — переобучение оплачивает Agentur für Arbeit."},"extra":"Лишние: obwohl, trotz, deren, darüber."},{"id":"s8t2","title":"Übung 8 · Teil 2","thema":"Angebot","type":"abc","head":"Ihr Schreiben vom 08.09.20xx<br>Unser Angebot „Datenschutz im Büro“, Angebotsnr. 2025-117","paras":["Sehr geehrte Frau Hartmann,","zunächst möchten wir uns für {52} vom 08.09.20xx bedanken. Wie telefonisch besprochen, erhalten Sie mit diesem Schreiben {53} für eine Datenschutz-Schulung Ihrer Mitarbeiter. Die Schulung bietet Ihrem Unternehmen {54}.","Ihre Mitarbeiter lernen, personenbezogene Daten sicher zu verarbeiten, und Sie vermeiden hohe Bußgelder. Weitere Informationen finden Sie in dem {55}.","Die Preise haben wir, wie gewünscht, an die Größe Ihres Unternehmens angepasst. Bitte beachten Sie, dass wir die Schulung frühestens drei Wochen {56} können.","Bei Fragen stehe ich Ihnen jederzeit zur Verfügung. Wir freuen uns auf Ihren Auftrag und sichern Ihnen eine pünktliche und {57} der Schulung zu.","Mit freundlichen Grüßen<br>Florian Wolf"],"items":[{"n":52,"o":["Ihre Anfrage","Ihr Interesse","Ihren Auftrag"],"a":0,"t":"Wortschatz","w":"für Ihre Anfrage vom 08.09. — благодарим за запрос (в шапке: Ihr Schreiben vom 08.09.). Заказа ещё нет — его только ждут."},{"n":53,"o":["unsere Bestellung","unser Angebot","unsere Nachfrage"],"a":1,"t":"Wortschatz","w":"erhalten Sie unser Angebot — в ответ на запрос фирма присылает предложение."},{"n":54,"o":["viele Nachteile","hohe Bußgelder","zahlreiche Vorteile"],"a":2,"t":"Wortschatz","w":"zahlreiche Vorteile — дальше перечислены плюсы. Bußgelder (штрафы) как раз избегают."},{"n":55,"o":["beiliegenden Unterlagen","beigefügten Prospekt","versendeten Rechnung"],"a":1,"t":"Deklination","w":"in dem beigefügten Prospekt — dem требует мужского или среднего рода: der Prospekt. Unterlagen — мн. ч. (den), Rechnung — женский род (der)."},{"n":56,"o":["nach Auftragserteilung durchführen","mit Bekanntgabe erledigen","nach Zusage herstellen"],"a":0,"t":"Wortschatz","w":"nach Auftragserteilung durchführen — провести после получения заказа."},{"n":57,"o":["kundengerechte Bearbeitung","schnelle Kündigung","ordnungsgemäße Durchführung"],"a":2,"t":"Wortschatz","w":"eine ordnungsgemäße Durchführung zusichern — гарантировать надлежащее проведение."}],"extra":"Полезные слова: personenbezogene Daten — персональные данные; das Bußgeld — штраф."},{"id":"s9t1","title":"Übung 9 · Teil 1","thema":"Weiterbildung","type":"bank","head":"","paras":["Sehr geehrte Damen und Herren,","vielen Dank für die {46} Zusendung Ihres Kursprogramms. Unsere Mitarbeiter interessieren sich sowohl für die Excel-Grundlagen als {47} für den Aufbaukurs.","Wir haben dazu allerdings {48} einige Fragen. Können wir bis zu zwölf Personen für den Online-Kurs anmelden? Und haben Sie {49} Erfahrung mit Kursen für Mitarbeiter aus der Logistik? Wenn nicht, würden wir lieber einen Kurs vor Ort buchen.","Wegen der Schichtarbeit haben unsere Mitarbeiter erst ab 16:00 Uhr Zeit. Wäre es möglich, den Kurs {50} 16:30 Uhr zu beginnen?","{51} möchten wir wissen, ob wir die Kursgebühren per Rechnung mit einem Zahlungsziel von 14 Tagen bezahlen können.","Vielen Dank im Voraus.","Mit freundlichen Grüßen<br>Paul Hermann"],"bank":[["a","noch"],["b","gegen"],["c","ob"],["d","auch"],["e","jedoch"],["f","sondern"],["g","deshalb"],["h","schon"],["i","schnelle"],["j","des Weiteren"]],"key":{"46":"i","47":"d","48":"a","49":"h","50":"b","51":"j"},"cap":[51],"topic":{"46":"Deklination","47":"Konnektor","48":"Adverb","49":"Adverb","50":"Präposition","51":"Konnektor"},"why":{"46":"die schnelle Zusendung — «быстрая отправка». Нужно прилагательное: после die — окончание -e.","47":"sowohl … als auch — «как…, так и». Парная связка.","48":"noch einige Fragen — «ещё несколько вопросов».","49":"schon — «уже»: Haben Sie schon Erfahrung …? — есть ли у вас уже опыт.","50":"gegen + время — «около»: gegen 16:30 Uhr.","51":"des Weiteren — «кроме того»: следующий вопрос. deshalb («поэтому») не подходит — причины нет."},"extra":"Лишние: ob, jedoch, sondern, deshalb."},{"id":"s9t2","title":"Übung 9 · Teil 2","thema":"Angebot","type":"abc","head":"Angebot","paras":["Sehr geehrte Frau Brandt,","vielen Dank für Ihr {52} an unseren Produkten. Gerne unterbreiten wir Ihnen {53}:","<div class=\"shb-tw\"><table class=\"shb-t\"><tr><th>Pos.</th><th>Bezeichnung</th><th>Menge</th><th>Einzelpreis (EUR)</th><th>Gesamt (EUR)</th></tr><tr><td>1.</td><td>Beamer „Vision X5“</td><td>3</td><td>890,00</td><td>2.670,00</td></tr><tr><td>2.</td><td>Installation</td><td>pauschal</td><td>350,00</td><td>350,00</td></tr><tr><td></td><td></td><td></td><td>Summe netto</td><td>3.020,00</td></tr><tr><td></td><td></td><td></td><td>Umsatzsteuer 19 %</td><td>573,80</td></tr><tr><td></td><td></td><td></td><td>Rechnungsbetrag</td><td>3.593,80</td></tr></table></div>","Die Lieferzeit beträgt etwa zwei Wochen, nachdem {54} wurde. Der Rechnungsbetrag ist innerhalb von 30 Tagen {55}. Die Garantie beträgt zwei Jahre. Dieses Angebot ist vier Wochen gültig.","Wir hoffen, dass unser Angebot {56}. Bei Fragen stehen wir Ihnen gerne {57}.","Mit freundlichen Grüßen<br>Martin Schuster"],"items":[{"n":52,"o":["Anfrage","Bestellung","Interesse"],"a":2,"t":"Rektion","w":"Interesse an + Dat. — интерес к: Ihr Interesse an unseren Produkten. Anfrage и Bestellung — женского рода, было бы Ihre."},{"n":53,"o":["laufende Kosten","folgendes Angebot","weitere Zusagen"],"a":1,"t":"Wortschatz","w":"Gerne unterbreiten wir Ihnen folgendes Angebot — «представляем вам следующее предложение». Дальше таблица с ценами."},{"n":54,"o":["der Auftrag erteilt","die Anfrage beantwortet","die Lieferung bekannt"],"a":0,"t":"Nomen-Verb-Verbindung","w":"nachdem der Auftrag erteilt wurde — после того как будет выдан заказ. Поставка идёт после заказа, а не после ответа на запрос."},{"n":55,"o":["ohne Abzug zu zahlen","mit Umsatzsteuer zu verkaufen","als Rabatt zu verbuchen"],"a":0,"t":"Wortschatz","w":"ohne Abzug zu zahlen — «оплатить без вычетов (без скидки)»."},{"n":56,"o":["einen Abnehmer findet","keine Kunden hat","Ihre Zustimmung findet"],"a":2,"t":"Nomen-Verb-Verbindung","w":"Ihre Zustimmung finden — «встретить ваше одобрение», стандартная формула."},{"n":57,"o":["zur Beratung","zur Verfügung","zur Hilfe"],"a":1,"t":"Nomen-Verb-Verbindung","w":"jdm. zur Verfügung stehen — быть в распоряжении. zur Beratung стоит только в связке zur Beratung zur Verfügung stehen."}]},{"id":"s10t1","title":"Übung 10 · Teil 1","thema":"Kündigung","type":"bank","head":"Kündigung meines Arbeitsvertrags","paras":["Sehr geehrter Herr Krämer,","hiermit kündige ich meinen Arbeitsvertrag fristgerecht zum 31.08.20xx. {46} mein Mann eine Stelle in München angenommen hat, ziehen wir im Sommer um, und ich kann leider nicht in Ihrem Betrieb bleiben.","Gleichzeitig beantrage ich meinen restlichen Urlaub von fünf Tagen, {47} mein letzter Arbeitstag der 24.08.20xx ist.","Bitte bestätigen Sie mir den Eingang meiner Kündigung. Außerdem bitte ich Sie, mir ein qualifiziertes Arbeitszeugnis auszustellen und es mir {48} mit den übrigen Arbeitspapieren an meine neue Adresse in München zu senden.","Die Übergabe meiner Kunden an meine Kollegin bereite ich {49} vor. Die Einzelheiten können wir gerne in einem Gespräch klären.","Ich habe in Ihrem Team immer {50} gern gearbeitet und viel gelernt. {51} danke ich Ihnen herzlich und wünsche Ihnen und dem ganzen Team alles Gute.","Freundliche Grüße<br>Olena Kravets"],"bank":[["a","als"],["b","da"],["c","dafür"],["d","dagegen"],["e","sehr"],["f","selbstverständlich"],["g","sodass"],["h","sowohl"],["i","zu"],["j","zusammen"]],"key":{"46":"b","47":"g","48":"j","49":"f","50":"e","51":"c"},"cap":[46,51],"topic":{"46":"Konnektor","47":"Konnektor","48":"Adverb","49":"Adverb","50":"Adverb","51":"da-Wort"},"why":{"46":"da — «так как»: причина в начале предложения (Da mein Mann … angenommen hat, …).","47":"sodass — «так что»: следствие — с пятью днями отпуска последним рабочим днём будет 24.08.","48":"zusammen mit — «вместе с»: прислать справку вместе с документами.","49":"selbstverständlich — «само собой разумеется»: передачу клиентов я, конечно, подготовлю.","50":"sehr gern — «очень охотно»: мне всегда очень нравилось работать в команде.","51":"dafür danke ich Ihnen — «за это благодарю»: danken für → dafür."},"extra":"Лишние: als, dagegen, sowohl, zu."},{"id":"s10t2","title":"Übung 10 · Teil 2","thema":"Beschwerde","type":"abc","head":"Weitere Zusammenarbeit","paras":["Sehr geehrter Herr Lindner,","am 3. März 20XX hatte ich Ihrer Agentur {52}, eine neue Website für unser Restaurant zu erstellen. Ihr Mitarbeiter, Herr Berger, hat sich danach mit mir {53} und einen ersten Termin für den 10. März vereinbart. Leider ist Herr Berger zu diesem Termin nicht gekommen.","Am nächsten Tag hat er sich telefonisch entschuldigt und {54}, am 14. März vorbeizukommen. Doch auch diesmal hat er {55}.","Da ich Herrn Berger nicht mehr erreiche, wende ich mich direkt an Sie. Bitte melden Sie sich {56} dieser Woche bei mir, damit wir besprechen können, wie es weitergeht. Ich bin sicher, dass wir gemeinsam {57}.","Mit freundlichen Grüßen<br>Elena Marino"],"items":[{"n":52,"o":["die Kündigung geschickt","den Auftrag erteilt","die Rechnung bezahlt"],"a":1,"t":"Nomen-Verb-Verbindung","w":"jdm. den Auftrag erteilen, etw. zu tun — поручить кому-то работу (выдать заказ)."},{"n":53,"o":["in Verbindung gesetzt","zur Sprache gebracht","zur Verfügung gestellt"],"a":0,"t":"Nomen-Verb-Verbindung","w":"sich mit jdm. in Verbindung setzen — связаться с кем-то. zur Sprache bringen — поднять тему; zur Verfügung stellen — предоставить."},{"n":54,"o":["mir sofort geholfen","mich kurz beantwortet","mir fest zugesagt"],"a":2,"t":"Wortschatz","w":"jdm. fest zusagen, etw. zu tun — твёрдо пообещать. Дальше: sein Versprechen — его обещание."},{"n":55,"o":["den Zweck nicht erfüllt","keine Verabredung getroffen","sein Versprechen nicht gehalten"],"a":2,"t":"Nomen-Verb-Verbindung","w":"ein Versprechen halten / nicht halten — сдержать / не сдержать обещание. Встречу они как раз назначили."},{"n":56,"o":["in Gang","im Laufe","im Grunde"],"a":1,"t":"Präposition","w":"im Laufe + Gen. — «в течение»: im Laufe dieser Woche. in Gang — «в ходу», im Grunde — «по сути»."},{"n":57,"o":["eine Lösung finden","am Ende sind","in Ordnung gehen"],"a":0,"t":"Nomen-Verb-Verbindung","w":"eine Lösung finden — найти решение. am Ende sein — выдохнуться; in Ordnung gehen — «быть в порядке»."}]}];
